let isResouceMatch=(ResourceToMatch:string){
    let resourceGroupsText = strcat_array(dynamic([{PlaybookResourceGroups}]),",");
    iff(strcat("",{PlaybookResourceGroups}) has "*",true, resourceGroupsText contains strcat("/resourceGroups/",tolower(ResourceToMatch)))
};
let isLAMatch=(LAToMatch:string){
    let LAGroupsText = strcat_array(dynamic([{PlaybookResources}]),",");
    iff(strcat("",{PlaybookResources}) has "*",true, LAGroupsText contains strcat("/workflows/",tolower(LAToMatch)))
};

AzureDiagnostics
| where ResourceProvider == "MICROSOFT.LOGIC" and isResouceMatch(ResourceGroup) == true 
| where OperationName startswith "Microsoft.Logic/workflows/workflowRun" and isLAMatch(resource_workflowName_s) == true
| make-series Trend = count() on TimeGenerated from {TimeRange:start} to {TimeRange:end} step {TimeRange:grain} by status_s
|join(
AzureDiagnostics
| where ResourceProvider == "MICROSOFT.LOGIC" and isResouceMatch(ResourceGroup) == true
| where OperationName startswith "Microsoft.Logic/workflows/workflowRun" and isLAMatch(resource_workflowName_s) == true
| summarize count() by status_s
) on status_s
| where status_s != "Running"
| order by status_s asc, count_
| project status_s,Trend, count_

